package net.civeira.phylax.feature.identity.tenantconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenantconfig.domain.TenantConfig;
import net.civeira.phylax.feature.identity.tenantconfig.domain.valueobject.AutoApproveRegisteredUsersVO;

class AutoApproveRegisteredUsersValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of auto approve registered users of tenant config")
  void test_auto_approve_registered_users_value_holder_assign_plain_value() {
    Object holder = new Object();
    AutoApproveRegisteredUsersValueHolder<Object> value =
        new AutoApproveRegisteredUsersValueHolder<>(holder);
    Assertions.assertSame(holder, value.autoApproveRegisteredUsers(true),
        "Setters must return the holder");
    Assertions.assertTrue(value.getAutoApproveRegisteredUsersValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(true, value.getAutoApproveRegisteredUsers().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.autoApproveRegisteredUsersNull(),
        "Setters must return the holder");
    Assertions.assertTrue(value.getAutoApproveRegisteredUsersValue().isPresent(),
        "A null value object must be stored");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of auto approve registered users of tenant config")
  void test_auto_approve_registered_users_value_holder_assign_value_object() {
    Object holder = new Object();
    AutoApproveRegisteredUsersValueHolder<Object> value =
        new AutoApproveRegisteredUsersValueHolder<>(holder);
    AutoApproveRegisteredUsersVO vo = AutoApproveRegisteredUsersVO.from(true);
    Assertions.assertFalse(value.getAutoApproveRegisteredUsersValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.autoApproveRegisteredUsers(vo),
        "Setters must return the holder");
    Assertions.assertSame(vo, value.getAutoApproveRegisteredUsersValue().orElseThrow());
    Assertions.assertSame(holder, value.autoApproveRegisteredUsers(Optional.empty()));
    Assertions.assertFalse(value.getAutoApproveRegisteredUsersValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.autoApproveRegisteredUsers(Optional.of(vo)));
    Assertions.assertSame(vo, value.getAutoApproveRegisteredUsersValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of auto approve registered users of tenant config against the original")
  void test_auto_approve_registered_users_value_holder_read() {
    Object holder = new Object();
    AutoApproveRegisteredUsersValueHolder<Object> value =
        new AutoApproveRegisteredUsersValueHolder<>(holder);
    AutoApproveRegisteredUsersVO vo = AutoApproveRegisteredUsersVO.from(true);
    AutoApproveRegisteredUsersVO other = AutoApproveRegisteredUsersVO.from(true);
    TenantConfig original = Mockito.mock(TenantConfig.class);
    Mockito.when(original.getAutoApproveRegisteredUsersValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readAutoApproveRegisteredUsers(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readAutoApproveRegisteredUsers(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.autoApproveRegisteredUsers(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readAutoApproveRegisteredUsers(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readAutoApproveRegisteredUsers(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of auto approve registered users of tenant config")
  void test_auto_approve_registered_users_value_holder_unset() {
    Object holder = new Object();
    AutoApproveRegisteredUsersValueHolder<Object> value =
        new AutoApproveRegisteredUsersValueHolder<>(holder);
    AutoApproveRegisteredUsersVO vo = AutoApproveRegisteredUsersVO.from(true);
    value.autoApproveRegisteredUsers(vo);
    Assertions.assertSame(holder,
        value.unsetAutoApproveRegisteredUsersIfMatches("autoApproveRegisteredUsers_other"));
    Assertions.assertTrue(value.getAutoApproveRegisteredUsersValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder,
        value.unsetAutoApproveRegisteredUsersIfMatches("autoApproveRegisteredUsers"));
    Assertions.assertFalse(value.getAutoApproveRegisteredUsersValue().isPresent(),
        "The field name must clear the value");
    value.autoApproveRegisteredUsers(vo);
    Assertions.assertSame(holder, value.unsetAutoApproveRegisteredUsers());
    Assertions.assertFalse(value.getAutoApproveRegisteredUsersValue().isPresent(),
        "Unset must clear the value");
  }
}
